package com.rulecraft.decisionops.workflow.api;
import com.rulecraft.decisionops.identity.security.CurrentUser;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService.*;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/change-requests")
public class ApprovalWorkflowController {private final ApprovalWorkflowService service;public ApprovalWorkflowController(ApprovalWorkflowService service){this.service=service;}@GetMapping WorkflowView workflow(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication auth){return service.workflow(CurrentUser.require(auth),projectId,serviceId);}@GetMapping("/{requestId}")RequestDetail detail(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,Authentication auth){return service.detail(CurrentUser.require(auth),projectId,serviceId,requestId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)RequestView create(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody CreateCommand body,Authentication auth){return service.create(CurrentUser.require(auth),projectId,serviceId,body);}@PostMapping("/{requestId}/submit")RequestView submit(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,@RequestBody TransitionCommand body,Authentication auth){return service.submit(CurrentUser.require(auth),projectId,serviceId,requestId,body);}@PostMapping("/{requestId}/request-changes")RequestView requestChanges(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,@RequestBody TransitionCommand body,Authentication auth){return service.requestChanges(CurrentUser.require(auth),projectId,serviceId,requestId,body);}@PostMapping("/{requestId}/approve")RequestView approve(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,@RequestBody TransitionCommand body,Authentication auth){return service.approve(CurrentUser.require(auth),projectId,serviceId,requestId,body);}@PostMapping("/{requestId}/reject")RequestView reject(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,@RequestBody TransitionCommand body,Authentication auth){return service.reject(CurrentUser.require(auth),projectId,serviceId,requestId,body);}@PostMapping("/{requestId}/promote")RequestView promote(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID requestId,@RequestBody TransitionCommand body,Authentication auth){return service.promote(CurrentUser.require(auth),projectId,serviceId,requestId,body);}}
